  const shifts=['All',...SHIFT_ORDER.filter(sh=>activeAttendanceEmployees().some(e=>e.shift===sh)),...Array.from(new Set(activeAttendanceEmployees().map(e=>e.shift).filter(Boolean))).filter(sh=>!SHIFT_ORDER.includes(sh))];
