function updateNoticeStatus(id){normalizeAttendance();const rec=(attendance.notices||[]).find(n=>String(n.id)===String(id));if(!rec)return;const st=val('noticeStatus_'+id)||rec.status;const dd=val('noticeDelivered_'+id)||rec.deliveredDate||'';const by=val('noticeBy_'+id)||rec.deliveredBy||'';const resp=val('noticeResponse_'+id)||rec.employeeResponse||'';if(st==='Void'&&!rec.voidReason){const reason=prompt('Reason for voiding this notice?');if(!reason)return;rec.voidReason=reason;}rec.status=st;rec.deliveredDate=dd;rec.deliveredBy=by;rec.employeeResponse=resp;rec.updatedAt=new Date().toISOString();audit('Attendance notice status updated',`${rec.employeeName||attendanceEmployeeNameById(rec.employeeId)} · ${st}`);saveAttendance('notice-status');toast('Notice updated');safeRenderPages({preserveScroll:true})}
